import {trackDraft} from './draft-guard.js';
// Shared local editor. Existing world databases are retained; drafts live only in memory.
const el=(tag,text,attrs={})=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);return e;};
const button=(label,fn,attrs={})=>{const e=el('button',label,{type:'button',...attrs});e.addEventListener('click',()=>Promise.resolve().then(fn).catch(console.error));return e;};
export function renderWorldNotes({main,world,name,scene,scenes,store,navigate,onDirty,draft='',announce}){
 let active=true,edit=null,original='',originalScene=scene||scenes[0].id,busy=false;const prefix=world+'-note';
 const heading=el('h1','Mis notas personales',{id:'view-title',tabindex:-1});main.append(el('p',name+' · Solo en este navegador',{class:'eyebrow'}),heading,el('p','Las notas se guardan en este navegador y dispositivo. Si lo compartes, otras personas con acceso podrían leerlas. No hay copia remota.',{class:'note'}));
 if(world==='alma'){const old=el('p',null,{class:'note'}),a=el('a','Tu refugio',{href:'#refugio','data-view':'refugio'});old.append('Tus ideas anteriores siguen disponibles en ',a,'.');main.append(old);}
 const details=el('details',null,{class:'notes-info'});details.append(el('summary','Sobre esta versión de evaluación'),el('p','Para probar la demostración, utiliza ejemplos ficticios, sin nombres, teléfonos ni información sensible. Borrar los datos del navegador puede eliminar las notas.',{class:'note'}));main.append(details);
 const form=el('form',null,{id:prefix+'-form',class:'panel shared-note-form',novalidate:''}),select=el('select',null,{id:prefix+'-scene'}),editor=el('textarea',null,{id:prefix+'-text',rows:6,maxlength:2000,'aria-describedby':prefix+'-hint '+prefix+'-status'});for(const s of scenes)select.append(el('option',s.title,{value:s.id}));select.value=originalScene;editor.value=draft;
 const status=el('p','',{id:prefix+'-status',role:'status',class:'message'}),save=el('button','Guardar nota',{id:prefix+'-save',type:'submit'}),cancel=button('Cancelar edición',()=>{if(!dirty()||confirm('¿Descartar los cambios de esta nota?'))reset();},{class:'secondary',id:prefix+'-cancel'});cancel.hidden=true;
 const controls=el('div',null,{class:'actions'});controls.append(save,cancel);form.append(el('label','Lugar',{for:select.id}),select,el('label','Tu nota',{for:editor.id}),editor,el('p','Hasta 2000 caracteres. Se guarda solo cuando pulsas Guardar nota.',{id:prefix+'-hint',class:'note'}),controls,status);const draftNotice=draft?el('p','Hemos preparado un borrador a partir de tu elección. Puedes cambiarlo, borrarlo o guardarlo.',{class:'note'}):null;if(draftNotice)form.prepend(draftNotice);
 const list=el('ul',null,{id:prefix+'-list',class:'shared-note-list'}),refresh=button('Consultar notas',()=>load(),{class:'secondary',id:prefix+'-refresh'}),newNote=button('Nueva nota',()=>{if(!dirty()||confirm('¿Descartar este borrador sin guardar?'))reset();},{class:'secondary',id:prefix+'-new'});const nav=el('div',null,{class:'actions'});nav.append(newNote,refresh);main.append(form,nav,list);
 function dirty(){return editor.value!==original||Boolean(editor.value.trim()&&select.value!==originalScene);}onDirty(dirty);trackDraft(dirty);
 function reset(){draftNotice?.remove();edit=null;original='';originalScene=scene||scenes[0].id;editor.value='';select.value=originalScene;select.disabled=false;save.textContent='Guardar nota';cancel.hidden=true;editor.focus();}
 function lock(v){busy=v;for(const b of main.querySelectorAll('button'))b.disabled=v;}
 const current=()=>active&&form.isConnected;
 async function load(){try{const all=await store.list();if(!current())return;list.replaceChildren();if(!all.length)list.append(el('li','Todavía no hay notas guardadas.'));for(const note of all){const item=el('li',null,{'data-note-id':note.id}),actions=el('div',null,{class:'actions'});actions.append(button('Editar',()=>{if(dirty()&&!confirm('¿Descartar este borrador para editar otra nota?'))return;draftNotice?.remove();edit=note.id;original=note.text;originalScene=note.scene;editor.value=note.text;select.value=note.scene;select.disabled=true;save.textContent='Guardar cambios';cancel.hidden=false;editor.focus();},{class:'secondary'}),button('Eliminar',async()=>{if(busy||!confirm('¿Eliminar esta nota? Esta acción no se puede deshacer.'))return;lock(true);try{await store.remove(note.id);if(!current())return;if(edit===note.id)reset();await load();status.textContent='Nota eliminada.';}catch(e){if(current())status.textContent=e.message;}finally{if(current())lock(false);}},{class:'secondary'}));item.append(el('h2',scenes.find(x=>x.id===note.scene)?.title||name),el('p',note.text,{class:'item-text'}),el('p','Guardada: '+new Date(note.updatedAt).toLocaleString('es-ES'),{class:'note'}),actions);list.append(item);}}catch(e){if(current())status.textContent=e.message;}}
 form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;lock(true);try{if(edit)await store.update(edit,editor.value);else await store.create(editor.value,select.value);if(!current())return;reset();await load();status.textContent='Nota guardada en este navegador.';announce?.(status.textContent);}catch(error){if(current()){status.textContent=error.message;editor.setAttribute('aria-invalid','true');}}finally{if(current())lock(false);}});load();
 return()=>{active=false;};
}
